import React from 'react';

import clsx from 'clsx';
import ExifReader from 'exifreader';

import { editImageAsync } from '@components/ImageEditor';
import { err } from '@helpers/notificationHelper';

import PohImagePlaceholder from '../ImagePlaceholder';
import { getImageNodeFromFile, validateFile, validateImage } from './imageUploaderHelper';
import { deleteByUrlAsync, IUploadBase64ResDTO, uploadBase64Async } from './service';
import style from './style.module.less';
import PohButton, { ButtonSize, ButtonVariant } from '../Button';
import PohIcon from '../Icon';
import IconsEnum from '../Icon/IconsEnum';
import PohLoader, { LoaderVariant } from '../Loader';

const defaultValidation = {
  fileFormats: ['image/bmp', 'image/gif', 'image/jpg', 'image/jpeg', 'image/png', 'image/heic'],
  maxWidth: 1920,
  maxHeight: 1080,
  size: 1024 * 1024, // bytes,
};

export interface IPohImageUploaderProps {
  src?: string;
  alt?: string;
  width?: number;
  height?: number;
  ratio?: number;
  quality?: number;
  mime?: number;
  folder?: string;
  onChange: (src: string | null, saveres?: IUploadBase64ResDTO, exifInfo?: ExifReader.Tags) => void;
  validation?: {
    fileFormats?: string[];
    maxWidth?: number;
    maxHeight?: number;
    size?: number;
  };
  editorTitle?: string;
  name?: string;
  sizes?: number[] | string[];
  includeExif?: boolean;
}

const PohImageUploader: React.FC<IPohImageUploaderProps> = ({
  src: defaultSrc,
  alt = 'Загрузить изображение',
  width = 255,
  height,
  ratio,
  quality,
  mime,
  editorTitle,
  folder = 'images',
  validation,
  onChange,
  sizes,
  name,
  includeExif,
}) => {
  const [src, setSrc] = React.useState<string>();
  const fileInputRef = React.useRef<HTMLInputElement>(null);
  const containerRef = React.useRef<HTMLDivElement>(null);
  const [isLoading, setIsLoading] = React.useState(false);
  const [preview, setPreview] = React.useState<string>();
  const [isDeleting, setIsDeleting] = React.useState(false);

  React.useEffect(() => {
    setSrc(defaultSrc);
  }, [defaultSrc]);

  const handleFileChange = (file: File) => {
    const validations = {
      ...defaultValidation,
      ...validation,
    };

    validateFile(file, validations)
      .then(getImageNodeFromFile)
      .then((img) => validateImage(img, validations))
      .then((imageNode) => {
        const imageOpts = {};
        width && Object.assign(imageOpts, { width });
        height && Object.assign(imageOpts, { height });
        ratio && Object.assign(imageOpts, { ratio });
        mime && Object.assign(imageOpts, { mime });
        quality && Object.assign(imageOpts, { quality });

        return editImageAsync(imageNode, imageOpts, editorTitle);
      })
      .then((base64) => {
        setIsLoading(true);
        setPreview(base64);
        return uploadBase64Async(base64, { folder, sizes, name });
      })
      .then(async ({ src: imgSrc, res: saveres }) => {
        setIsLoading(false);
        setPreview(undefined);

        let tags;
        if (includeExif) {
          tags = await ExifReader.load(file);
        }

        onChange(imgSrc, saveres, tags);
        setSrc(imgSrc);
      })
      .catch((e) => {
        console.error(e);
        err(e.message);
      });
  };

  React.useEffect(() => {
    const activeClass = 'bg-warning';

    function preventDefaults(e: Event) {
      e.preventDefault();
      e.stopPropagation();
    }

    ['dragenter', 'dragover', 'dragleave', 'drop'].forEach((eventName) => {
      containerRef.current &&
        containerRef.current.addEventListener(eventName, preventDefaults, false);
    });

    function highlight() {
      containerRef.current && containerRef.current.classList.add(activeClass);
    }

    function unhighlight() {
      containerRef.current && containerRef.current.classList.remove(activeClass);
    }

    ['dragenter', 'dragover'].forEach((eventName) => {
      containerRef.current && containerRef.current.addEventListener(eventName, highlight, false);
    });

    ['dragleave', 'drop'].forEach((eventName) => {
      containerRef.current && containerRef.current.addEventListener(eventName, unhighlight, false);
    });

    const handleDrop = async (event: DragEvent) => {
      event.dataTransfer && handleFileChange(event.dataTransfer.files[0]);
    };

    const handlePaste = async (event: ClipboardEvent) => {
      event.clipboardData && handleFileChange(event.clipboardData.files[0]);
    };

    containerRef.current && containerRef.current.addEventListener('drop', handleDrop);
    containerRef.current && containerRef.current.addEventListener('paste', handlePaste);

    return () => {
      ['dragenter', 'dragover', 'dragleave', 'drop'].forEach((eventName) => {
        containerRef.current &&
          containerRef.current.removeEventListener(eventName, preventDefaults, false);
      });
      ['dragenter', 'dragover'].forEach((eventName) => {
        containerRef.current &&
          containerRef.current.removeEventListener(eventName, highlight, false);
      });

      ['dragleave', 'drop'].forEach((eventName) => {
        containerRef.current &&
          containerRef.current.removeEventListener(eventName, unhighlight, false);
      });
      containerRef.current && containerRef.current.removeEventListener('drop', handleDrop);
      containerRef.current && containerRef.current.removeEventListener('paste', handlePaste);
    };
  }, []);

  if (isLoading) {
    return (
      <section className={clsx('form-control', style.imageUpload)} ref={containerRef}>
        <div className="position-relative">
          <PohImagePlaceholder src={`${preview}`} alt={alt} style={{ filter: 'blur(4px)' }} />
          <div
            style={{ inset: 0, backgroundImage: `url(${preview})` }}
            className="position-absolute d-flex align-items-center justify-content-between"
          >
            <div className="text-center w-100">
              <PohLoader variant={LoaderVariant.Dark} />
              <br />
              Загрузка на сервер...
            </div>
          </div>
        </div>
      </section>
    );
  }

  return (
    <section className={clsx('form-control', style.imageUpload)} ref={containerRef} tabIndex={1}>
      {src && (
        <section className={style.imageContainer}>
          {isDeleting && (
            <div
              style={{ inset: 0 }}
              className="position-absolute d-flex align-items-center justify-content-between"
            >
              <div className="text-center w-100">
                <PohLoader variant={LoaderVariant.Dark} />
                <br />
                Удаление с сервера...
              </div>
            </div>
          )}
          {!isDeleting && (
            <PohButton
              icon={IconsEnum.close}
              className={style.delBtn}
              title="Удалить/Изменить изображение"
              disabled={isDeleting}
              onClick={async () => {
                try {
                  setIsDeleting(true);
                  await deleteByUrlAsync(src);
                } finally {
                  setIsDeleting(false);
                  setSrc(undefined);
                  onChange(null);
                }
              }}
            />
          )}
          <PohImagePlaceholder src={src} alt={alt} style={{ opacity: isDeleting ? 0.5 : 1 }} />
        </section>
      )}
      {!src && (
        <div className="text-center text-muted p-2">
          <PohIcon src="" className="mt-3" name={IconsEnum.download} />
          <div className={clsx('mt-1', style.caption)}>
            Перетащить изображение,
            <br />
            вставить из буфера
          </div>
          <div className={clsx('my-1', style.or)}>или</div>
          <input
            type="file"
            accept="image/*"
            className={style.hiddenInput}
            ref={fileInputRef}
            onChange={({ target }) => target.files && handleFileChange(target.files[0])}
          />
          <PohButton
            className="mb-1"
            size={ButtonSize.Small}
            variant={ButtonVariant.Light}
            onClick={() => fileInputRef.current && fileInputRef.current.click()}
          >
            Загрузить
          </PohButton>
        </div>
      )}
    </section>
  );
};

export default PohImageUploader;
